 84      const normalizedApiKey = String(apiKey || '').trim();
 85      if (!normalizedApiKey) {
 86        return Promise.reject(new Error('Missing Google Maps browser API key.'));
 87      }
 88      if (window.google?.maps?.importLibrary) {
 89        return Promise.resolve();
 90      }
