async () => {
  const helpers = window.FamilyAssistantHelpers;
  const cards = document.createElement('div');
  document.body.appendChild(cards);
  const apiKey = document.getElementById('clancy-root').dataset.googleMapsClientApiKey;
  // Try with a fake/invalid token to see if PlaceContextualElement exists
  try {
    helpers.renderGoogleMapsGroundingWidget(
      { google_maps_grounding: { widget_context_tokens: ['widgetcontent/fake-token-for-test'] } },
      cards,
      { apiKey }
    );
  } catch (e) {
    return { error: String(e) };
  }
  // Wait for async load
  await new Promise(r => setTimeout(r, 4000));
  return {
    cardChildren: cards.children.length,
    cardHTML: cards.innerHTML.slice(0, 400),
    mapsLoaded: !!window.google?.maps?.importLibrary,
    placesObj: !!window.google?.maps?.places,
    placeContextualElement: typeof window.google?.maps?.places?.PlaceContextualElement,
  };
}

